-- ============================================================================
-- 040c_entity_pricing_component.sql
-- Concept: Register document.pricing_component (PC) as a control.entity
-- Depends on: 040_entity.sql (base entity registry)
-- Spec: docs/specs/purchase_invoice_field_design.md §3.3
--
-- PC is a polymorphic DOCUMENT_RELATION (similar to accounting_distribution):
--   • parent is the source_doc (PI or PIL) via source_doc_type discriminator
--   • auto_generated by the pricing-component service
--   • no status column on PC itself — supersede chain handles in-draft history
-- ============================================================================

INSERT INTO control.entity (
    tenant_id,
    module_id,
    name, slug,
    entity_short, entity_code, entity_class,
    ownership_model,
    kind, backing_type,
    governance_level, security_tier, mutability,
    mapping_mode,
    table_schema, table_name,
    label_singular, label_plural,
    icon_key, color_token,
    display_config, feature_flags,
    data_policy, identity_config, search_config, concurrency_policy,
    status, created_by, updated_by
)
SELECT NULL,
       'ACC',
       'pricing_component', 'pricing-component',
       'PC', 'pricing_component', 'DOCUMENT_RELATION',
       'system',
       'ent', 'table',
       'full', 'tenant_critical', 'controlled',
       'exclusive',
       'document', 'pricing_component',
       'Pricing Component', 'Pricing Components',
       'percent', 'amber',
       '{"line_ui_variant":"pricing"}'::jsonb,
       '{"polymorphic_parent":true,"parent_source_type_field":"source_doc_type","parent_source_id_field":"source_doc_id","parent_source_line_field":"source_line_id","auto_generated":true,"supersede_chain":true,"no_status":true}'::jsonb,
       '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb,
       'ACTIVE',
       '00000000-0000-0000-0000-000000000000',
       NULL
 WHERE NOT EXISTS (
    SELECT 1 FROM control.entity
     WHERE table_schema = 'document' AND table_name = 'pricing_component' AND tenant_id IS NULL
 );

-- Create the v1 entity_version row (EFFECTIVE)
INSERT INTO control.entity_version (
    tenant_id, entity_id, version_no, label,
    status, effective_from, created_by
)
SELECT NULL, e.id, 1, 'v1',
       'EFFECTIVE', now(), '00000000-0000-0000-0000-000000000000'
  FROM control.entity e
 WHERE e.table_schema = 'document'
   AND e.table_name   = 'pricing_component'
   AND e.tenant_id IS NULL
   AND NOT EXISTS (
        SELECT 1 FROM control.entity_version ev
         WHERE ev.entity_id = e.id AND ev.version_no = 1
   );


-- =============================================================================
-- End of 040c_entity_pricing_component.sql
-- =============================================================================
